@Target(AnnotationTarget.CLASS)
@Retention(AnnotationRetention.RUNTIME)
annotation class ContentType(val name: String)

@ContentType("expense")
data class Expense(val amount: Double)

@DslMarker annotation class ExpenseDsl
@ExpenseDsl class ReportBuilder {
    private val items = mutableListOf<Expense>()
    fun expense(category: String, amount: Double) {
        items += Expense(category, amount)
    }
    fun build(): List<Expense> = items.toList()
}
fun report(block: ReportBuilder.() -> Unit): List<Expense> =
    ReportBuilder().apply(block).build()

