data class Expense(val category: String, val amount: Double)
class ReportBuilder {
    private val values = mutableListOf<Expense>()
    fun expense(category: String, amount: Double) { values += Expense(category, amount) }
    fun build(): List<Expense> = values.toList()
}
fun report(block: ReportBuilder.() -> Unit) = ReportBuilder().apply(block).build()
fun main() {
    val values = report { expense("Food", 6.0); expense("Travel", 9.0) }
    println(values.sumOf { it.amount })
}
